const monitoringGrantResourceExists = `-- name: MonitoringGrantResourceExists :one
SELECT EXISTS(
 SELECT a.id FROM monitoring_applications a WHERE a.enterprise_id=$1 AND a.id=$2 AND $3::text='application' AND a.status='active'
 UNION ALL SELECT t.id FROM monitoring_targets t WHERE t.enterprise_id=$1 AND t.id=$2 AND $3::text='monitoring_target' AND t.status='active'
 UNION ALL SELECT n.id FROM kubernetes_namespace_resources n WHERE n.enterprise_id=$1 AND n.id=$2 AND $3::text='kubernetes_namespace' AND n.status='active'
)::boolean
`

type MonitoringGrantResourceExistsParams struct {
	EnterpriseID uuid.UUID `json:"enterprise_id"`
	ID           uuid.UUID `json:"id"`
	ResourceType string    `json:"resource_type"`
}

func (q *Queries) MonitoringGrantResourceExists(ctx context.Context, arg MonitoringGrantResourceExistsParams) (bool, error) {
	row := q.db.QueryRow(ctx, monitoringGrantResourceExists, arg.EnterpriseID, arg.ID, arg.ResourceType)
	var column_1 bool
	err := row.Scan(&column_1)
	return column_1, err
}

const observeMonitoringApplicationService = `-- name: ObserveMonitoringApplicationService :exec
UPDATE monitoring_application_services service SET first_seen_at=COALESCE(service.first_seen_at,now()),last_seen_at=now()
FROM monitoring_applications application
WHERE service.enterprise_id=$1 AND service.id=$2 AND service.application_id=$3 AND service.status='active'
AND application.enterprise_id=service.enterprise_id AND application.id=service.application_id AND application.status='active'
`

type ObserveMonitoringApplicationServiceParams struct {
	EnterpriseID  uuid.UUID `json:"enterprise_id"`
	ID            uuid.UUID `json:"id"`
	ApplicationID uuid.UUID `json:"application_id"`
}

func (q *Queries) ObserveMonitoringApplicationService(ctx context.Context, arg ObserveMonitoringApplicationServiceParams) error {
	_, err := q.db.Exec(ctx, observeMonitoringApplicationService, arg.EnterpriseID, arg.ID, arg.ApplicationID)
	return err
}

const observeMonitoringInstance = `-- name: ObserveMonitoringInstance :one
INSERT INTO monitoring_runtime_instances(id,enterprise_id,service_id,instance_key,placement,last_seen_at)
VALUES($1,$2,$3,$4,$5,$6)
ON CONFLICT(service_id,instance_key) DO UPDATE SET
 placement=CASE WHEN EXCLUDED.last_seen_at>=monitoring_runtime_instances.last_seen_at THEN EXCLUDED.placement ELSE monitoring_runtime_instances.placement END,
 last_seen_at=GREATEST(EXCLUDED.last_seen_at,monitoring_runtime_instances.last_seen_at)
RETURNING id, enterprise_id, service_id, instance_key, placement, first_seen_at, last_seen_at
`

type ObserveMonitoringInstanceParams struct {
	ID           uuid.UUID          `json:"id"`
	EnterpriseID uuid.UUID          `json:"enterprise_id"`
	ServiceID    uuid.UUID          `json:"service_id"`
	InstanceKey  string             `json:"instance_key"`
	Placement    []byte             `json:"placement"`
	LastSeenAt   pgtype.Timestamptz `json:"last_seen_at"`
}

func (q *Queries) ObserveMonitoringInstance(ctx context.Context, arg ObserveMonitoringInstanceParams) (MonitoringRuntimeInstance, error) {
	row := q.db.QueryRow(ctx, observeMonitoringInstance,
		arg.ID,
		arg.EnterpriseID,
		arg.ServiceID,
		arg.InstanceKey,
		arg.Placement,
		arg.LastSeenAt,
	)
	var i MonitoringRuntimeInstance
	err := row.Scan(
		&i.ID,
		&i.EnterpriseID,
		&i.ServiceID,
		&i.InstanceKey,
		&i.Placement,
		&i.FirstSeenAt,
		&i.LastSeenAt,
	)
	return i, err
}

