const upsertKubernetesNamespaceResource = `-- name: UpsertKubernetesNamespaceResource :one
INSERT INTO kubernetes_namespace_resources(id,enterprise_id,cluster_id,namespace_uid,name,resource_version,observed_at)
VALUES($1,$2,$3,$4,$5,$6,clock_timestamp())
ON CONFLICT(cluster_id,namespace_uid) DO UPDATE SET name=EXCLUDED.name,resource_version=CASE WHEN EXCLUDED.resource_version<>'' THEN EXCLUDED.resource_version ELSE kubernetes_namespace_resources.resource_version END,
 status='active',observed_at=clock_timestamp(),version=kubernetes_namespace_resources.version+
 CASE WHEN kubernetes_namespace_resources.name<>EXCLUDED.name OR kubernetes_namespace_resources.status<>'active' THEN 1 ELSE 0 END RETURNING id, enterprise_id, cluster_id, namespace_uid, name, status, resource_version, observed_at, version
`

type UpsertKubernetesNamespaceResourceParams struct {
	ID              uuid.UUID `json:"id"`
	EnterpriseID    uuid.UUID `json:"enterprise_id"`
	ClusterID       uuid.UUID `json:"cluster_id"`
	NamespaceUid    string    `json:"namespace_uid"`
	Name            string    `json:"name"`
	ResourceVersion string    `json:"resource_version"`
}

func (q *Queries) UpsertKubernetesNamespaceResource(ctx context.Context, arg UpsertKubernetesNamespaceResourceParams) (KubernetesNamespaceResource, error) {
	row := q.db.QueryRow(ctx, upsertKubernetesNamespaceResource,
		arg.ID,
		arg.EnterpriseID,
		arg.ClusterID,
		arg.NamespaceUid,
		arg.Name,
		arg.ResourceVersion,
	)
	var i KubernetesNamespaceResource
	err := row.Scan(
		&i.ID,
		&i.EnterpriseID,
		&i.ClusterID,
		&i.NamespaceUid,
		&i.Name,
		&i.Status,
		&i.ResourceVersion,
		&i.ObservedAt,
		&i.Version,
	)
	return i, err
}
